export interface ReserveAllocation {
  allocated: Numeric;
  company_id: string;
  /**
   * ADR-027. How much of the allocated reserve has been drawn. NOT the sum of follow-on rounds, and the difference is not rounding: C001 in the reference dataset reads 1.5 against a 3.5 follow-on, C004 reads 6.0 against 8.0. A follow-on can be funded from a new allocation rather than the reserve, and a reserve can be released without being deployed. Reserve accounting is a decision the investment team records, not an arithmetic consequence of the transactions.
   */
  deployed: Generated<Numeric>;
  effective_from: Generated<Timestamp>;
  policy_basis: string | null;
  reserve_allocation_id: Generated<Int8>;
  set_at: Generated<Timestamp>;
  set_by: string;
}

export interface RoundCoinvestor {
  amount: Numeric | null;
  /**
   * ADR-031 soft delete. A co-investor removed from a round leaves v_lp_capital_to_direct and the NB co-investment aggregate, and stays restorable.
   */
  deleted_at: Timestamp | null;
  deleted_by: string | null;
  deleted_reason: string | null;
  fund_investment_id: string | null;
  investment_round_id: Int8;
  investor_name: string;
  is_nb_based: Generated<boolean>;
  /**
   * ADR-020. Added at A8; the A6 generator had been writing these rows without it, so a co-investor was the one generated financial row that could not be identified as generated. Backfilled from the parent round.
   */
  is_synthetic: Generated<boolean>;
  round_coinvestor_id: Generated<Int8>;
  row_created_at: Generated<Timestamp>;
  row_updated_at: Generated<Timestamp>;
}

