export interface Transaction {
  /**
   * Always positive. Direction is implied by txn_type. Capital drawdowns are outflows, capital distributions are inflows.
   */
  amount: Numeric;
  batch_id: string | null;
  booked_at: Generated<Timestamp>;
  company_id: string | null;
  currency: Generated<string>;
  /**
   * ADR-031 soft delete. A row booked against the wrong company is deleted and re-entered rather than edited into an unrelated fact. Excluded from v_transaction_live and therefore from every aggregate.
   */
  deleted_at: Timestamp | null;
  deleted_by: string | null;
  deleted_reason: string | null;
  entered_by: string;
  fund_investment_id: string | null;
  fx_rate_to_cad: Numeric | null;
  /**
   * What this cheque bought. NOT the round's instrument, though it usually matches: a round can be funded with a note alongside equity, and a company can hold both an equity position and an outstanding loan. NOT company.instrument_id either, which ADR-027 records as an independent headline fact rather than a derivation. NULL = unrecorded, never defaulted, on the ADR-030 precedent.
   */
  instrument_id: number | null;
  investment_round_id: Int8 | null;
  investment_vehicle_id: number | null;
  is_synthetic: Generated<boolean>;
  note: string | null;
  reverses_transaction_id: Int8 | null;
  row_created_at: Generated<Timestamp>;
  row_updated_at: Generated<Timestamp>;
  source_document: string | null;
  /**
   * ADR-033. Set when someone has confirmed that this cheque correctly belongs to no round -- a bridge note, a standalone convertible, a secondary purchase. Distinguishes that from a cheque nobody has reviewed, which is the distinction the F6 unlinked-cheque check needs in order to ever reach zero. Cleared automatically when a round is attached: the two statements cannot both be true.
   */
  standalone_confirmed_at: Timestamp | null;
  standalone_confirmed_by: string | null;
  transaction_id: Generated<Int8>;
  txn_date: Timestamp;
  /**
   * FR-33, ADR-037 clause 4. LP activity is `capital_drawdown` / `capital_distribution` / `fee` -- NBIF's words, confirmed with Funke at Q-23. From the GP's side a drawdown is a capital call; from ours it is a draw against a commitment we already made, and the platform speaks from our side. Direct activity is investment / follow_on / realization / write_off and has never used either LP string.
   */
  txn_type: string;
  voided_at: Timestamp | null;
  voided_by_transaction_id: Int8 | null;
  voided_reason: string | null;
}

export interface ValuationMark {
  /**
   * The INPUT to a transaction-driven mark, when Q-3 is answered. NULL on every path F2 builds. Never populated for a review, where the amount is fmv - basis_fmv and storing it would be storing a sum (ADR-002).
   */
  adjustment_amount: Numeric | null;
  /**
   * ADR-034. What caused this mark. `review` and `manual` are the two paths F2 builds; `legacy` labels every row that predates F2. The rest are declared and written by nothing -- `transaction` and `round_reprice` wait on Q-2/Q-3/Q-4, `realization` on Q-12, `write_off` on F4. They are in the vocabulary now because none of those answers changes the shape of a row, only which rows get written.
   */
  adjustment_type: Generated<string>;
  /**
   * ADR-034 clause 3. The basis mark's FMV AT THE TIME THIS ROW WAS WRITTEN, stored rather than looked up. A later correction to an earlier mark therefore becomes a detectable inconsistency -- this value no longer matching its predecessor -- rather than silently invalidating every mark downstream. F6 reports the mismatch.
   */
  basis_fmv: Numeric | null;
  basis_mark_id: Int8 | null;
  booked_at: Generated<Timestamp>;
  company_id: string;
  currency: Generated<string>;
  deleted_at: Timestamp | null;
  deleted_by: string | null;
  deleted_reason: string | null;
  effective_date: Timestamp;
  fmv: Numeric;
  is_synthetic: Generated<boolean>;
  /**
   * ADR-026. The verbatim method string the ADR-001 contract carries, which the API serialises. Marks routinely qualify a canonical method in free text - "Revenue multiple, discounted", "Last round + backlog coverage" - and that qualification is meaningful to whoever reads the mark. valuation_method_id resolves to ref_valuation_method only on an exact match and is NULL otherwise; it is what grouping and filtering use.
   */
  method_label: string;
  prepared_by: string | null;
  prepared_by_label: string;
  /**
   * Not optional. This is what a board or auditor reads when they challenge a number.
   */
  rationale: string;
  /**
   * RETAINED value. 0.7500 = carried at 75% of the basis, a 25% impairment. The INPUT to a review; `fmv` is the result and is computed server-side, never accepted from the client (ADR-034 clause 2).
   */
  retention_factor: Numeric | null;
  row_created_at: Generated<Timestamp>;
  row_updated_at: Generated<Timestamp>;
  source_document: string | null;
  status: Generated<string>;
  supersedes_id: Int8 | null;
  valuation_mark_id: Generated<Int8>;
  valuation_method_id: number | null;
}

